interactions.sample_code:
function leftRotate(T, x) {
  const y = right(x);              // y becomes the new subtree root
  note('y = x.right');
  setRight(x, left(y));            // beta moves to x's right
  note('beta reparented to x');
  replaceInParent(x, y);           // y takes x's place under the parent
  note('y linked to x.p');
  setLeft(y, x);                   // x becomes y's left child
  note('x is now y.left');
}

interactions.buggy_code:
function leftRotate(T, x) {
  const y = right(x);
  setLeft(y, x);                   // BUG: attaching x before moving beta
  setRight(x, left(y));            // left(y) is now x itself — beta is lost and x points at itself
  replaceInParent(x, y);
}

